insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('02afe4c6-daf4-4451-8f19-86b5f5aa549f', '04f9acb7-7f17-43d8-a355-96924ed11311', $$bron 1: pagina uit het boek van architect Andrea Palladio (16e eeuw)$$,
   $$geschiedenis-havo-2022-ii-ontdekkers-en-hervormers-bron1.png$$,
   $$bron 1 Pagina uit het boek van de architect Andrea Palladio (1508-1580):
[Afbeelding] Gravure: gedetailleerde bouwtekening van een klassieke zuil met kapiteel en kroonlijst, met letters en maataanduidingen in de kantlijn.
Toelichting: Palladio maakt tijdens zijn rondreis door Italië schetsen van Romeinse zuilen en gebouwen en neemt de afmetingen op. Deze schetsen gebruikt hij voor zijn eigen ontwerpen.$$, 'inline'),
  ('5a18e299-6184-4136-8861-a160843a4873', '2cb9561d-7c02-48bc-9b14-755c69e765fc', $$bron 2: brief van kolonist John Smith over de kolonie bij Chesapeake Bay (1607)$$,
   $$geschiedenis-havo-2022-ii-het-britse-rijk-bron2.png$$,
   $$bron 2 In 1607 vestigen Engelse kolonisten zich bij Chesapeake Bay, aan de noordoostkust van Amerika. Een van de kolonisten, John Smith, schrijft na enkele maanden hierover in een brief aan een vriend in Engeland:
Ons fort werd daarna omheind en alle mannen waren in goede gezondheid en comfortabel; dit hield helaas maar even stand vanwege onverenigbare karakters. De president1) en kapitein Gosnold en de rest van de raad waren ontevreden over elkaars handelen; zelfs zo erg dat zaken onverstandig werden aangepakt, zodat de toestand niet goed was en ook niet veilig. En door het harde optreden van de president, waarbij de rest van raad verdeeld was over zijn leiderschap (…) werden we geplaagd door honger en ziektes. Het was zo erg dat de levenden nauwelijks de doden konden begraven. We hadden behoefte aan voldoende levensmiddelen van kwaliteit, vooral omdat we elk vier van de vijf nachten op wacht moesten staan op onze drie verschansingen (…): de voorraden, de aquavit [sterke drank] en andere middelen die we nodig hadden, werden door de president voor zichzelf en zijn vertrouwelingen gehouden.
noot 1 Dit is Edward Maria Wingfield, die is aangesteld als de president van de kolonie in Chesapeake Bay.$$, 'inline'),
  ('bc70bb85-4c56-49c6-9232-9e93d397df1d', '2cb9561d-7c02-48bc-9b14-755c69e765fc', $$bron 4: petitie van een groep hindoes tegen het verbod op sati (1829)$$,
   $$geschiedenis-havo-2022-ii-het-britse-rijk-bron4.png$$,
   $$bron 4 In 1829 verbiedt het Britse bestuur in India Sati, een religieus gebruik onder sommige Hindoes, waarbij een weduwe levend wordt verbrand op de brandstapel van haar overleden man. Een groep Hindoes schrijft hierna in een petitie aan de Britse gouverneur-generaal:
We horen met verbazing en verdriet dat de afschaffing van de praktijk van Sati wordt verdedigd door te beweren dat er geen wet over bestaat: een gedachte die wordt verspreid door een groep Hindoes die zich van de religie van hun voorvaderen heeft afgekeerd, die zichzelf heeft vervuild met verboden eten en drinken uit de Europese samenleving. En zij zet zich in om u wijs te maken dat er geen wet is over het ritueel van Sati en dat alle intelligente en geschoolde Hindoes het eens zijn met de afschaffing ervan. (…) Maar wij leggen eerbiedig voor dat een kwestie zo gevoelig als deze, over de interpretatie van onze heilige boeken en het bestaansrecht van onze heilige gebruiken, niemand behalve pundits [Hindoe geleerden] en brahmanen [Hindoe priesters] geconsulteerd mogen worden.$$, 'inline'),
  ('f4227d2f-03f5-4e12-acbf-04aa0539300b', '2cb9561d-7c02-48bc-9b14-755c69e765fc', $$bron 5: brief van een fabriekseigenaar in een inspectieverslag (1845)$$,
   $$geschiedenis-havo-2022-ii-het-britse-rijk-bron5.png$$,
   $$bron 5 In 1845 krijgt James Graham, de minister van Binnenlandse Zaken een verslag1) met daarin een brief van een fabriekseigenaar:
Het is mijn bedoeling om de werktijd verder te verminderen tot tien en een half uur (…). Ik merk dat de arbeiders met meer energie en geest werken; ze zijn vrolijker en blijer. Alle argumenten die ik lange tijd heb gehoord tegen werktijdvermindering zijn gebaseerd op een rekenkundige vraag - als een elf-urige werkdag zoveel productie oplevert, wat levert twaalf of vijftien uur dan op? Dit is een juiste vraag voor de stoommachine (…), maar probeer dit voor een paard, en je zult merken dat hij niet kan concurreren met de motor, omdat hij tijd nodig heeft om te rusten en te eten.
noot 1 Door de regering aangestelde inspecteurs zenden twee maal per jaar een verslag van hun inspecties van fabrieken naar het ministerie van Binnenlandse Zaken. De brief van de fabriekseigenaar komt uit het verslag van de periode van 30 september 1844 tot 30 april 1845.$$, 'inline'),
  ('1a46eacb-4c6a-469e-9996-44457d7d99da', 'd149e5ac-d8c1-488d-a064-86690e544424', $$bron 3: oproep van Herman Willem Daendels aan Gelderse en Overijsselse landgenoten (1794)$$,
   $$geschiedenis-havo-2022-ii-pruiken-en-revoluties-bron3.png$$,
   $$bron 3 In 1794 doet Herman Willem Daendels een oproep:
Daendels, generaal-majoor (van de brigade) bij het Franse leger, aan zijn Gelderse en Overijsselse landgenoten! Ontwaakt mijne waarde landgenoten. De tijd is gekomen dat wij ons zelf moeten verlossen van de slavernij waaronder het land en vooral de boerenstand zo lang gezucht heeft. Aarzel niet de wapens op te pakken en u te ontdoen van uw drosten, hoofdschouten, richters, ambts-jonkers, schouten, collecteurs, pachters1) en andere beulen en bloedzuigers. (…) Ik en andere Gelderse en Overijsselse jongens, die onder de Fransen het kunstje van de oorlog geleerd hebben, staan gereed. U zult binnenkort zien hoe die mooi-gepoederde officiertjes en soldaten op de loop gaan voor boerenjongens in hun linnen kielen.
noot 1 Verschillende machthebbers op het gebied van orde, rechtsspraak en belastingen.
Toelichting: Herman Willem Daendels is de zoon van de stadssecretaris van Hattem in Gelderland. Hij vlucht in 1787 naar Frankrijk nadat hij kritiek heeft geuit op het beleid van de regenten en de stadhouder in de Republiek$$, 'inline'),
  ('4672919d-7a12-45c9-a440-7086fdda3cd9', '994edf08-89c6-4f2d-8991-03d9319e54f3', $$bron 6: herinnering van de katholieke schrijver Gerard Brom aan zijn studententijd$$,
   $$geschiedenis-havo-2022-ii-burgers-en-stoommachines-bron6.png$$,
   $$bron 6
De katholieke schrijver Gerard Brom (1882-1959) herinnert zich over zijn studententijd in Utrecht:
In Utrecht trokken katholieke studenten er niet zoals in Amsterdam op uit om huis aan huis in volksbuurten propaganda bij de verkiezingen te maken, maar ik heb wel bij de uitbreiding van het kiesrecht huisbezoeken gedaan voor het werven van nieuwe kiezers onder arbeiders die zich moeilijk lieten overtuigen.$$, 'inline'),
  ('67d22d47-fc4d-4505-b341-a705a50fdcaf', 'e1b46de3-9810-4f87-ad4a-f5d6678e2c05', $$bron 7: instructie van de NSDAP-partijleiding aan lokale afdelingen (1933)$$,
   $$geschiedenis-havo-2022-ii-duitsland-in-europa-bron7.png$$,
   $$bron 7 Op 28 maart 1933 stuurt de partijleiding van de NSDAP een instructie naar lokale partijafdelingen:
Actiecomités moeten streng controleren in hoeverre [Duitse] kranten deelnemen aan de voorlichtingscampagne tegen het afschuwelijke haatzaaien door Joden in het buitenland. Als kranten dat niet of maar in beperkte mate doen, dan moet erop worden toegezien, dat zij ogenblikkelijk worden verwijderd uit ieder huis waar Duitsers wonen. Geen enkele Duitser of Duitse zaak moet in zulke kranten nog advertenties plaatsen. Die kranten moeten openlijk worden veracht. Zij zijn geschreven voor Joden, maar niet voor het Duitse volk.$$, 'inline'),
  ('297098e5-aebe-4f65-afde-07ea95d51735', 'e1b46de3-9810-4f87-ad4a-f5d6678e2c05', $$bron 9: prent van L.J. Jordaan in Het Parool over de arbeidersopstand in de DDR (1953)$$,
   $$geschiedenis-havo-2022-ii-duitsland-in-europa-bron9.png$$,
   $$bron 9 Naar aanleiding van de arbeidersopstand in de DDR verschijnt op 23 juni 1953 deze prent van L.J. Jordaan in het dagblad Het Parool:
[Afbeelding] Prent in twee delen: links slaat een vuist aan een arm met een hakenkruisband een arbeider neer, met Mussert achter de arm; rechts slaat een vuist aan een arm met hamer en sikkel een arbeider neer, met Ulbricht en Grotewohl achter de arm.
Toelichting:
Bij het linkerdeel van de prent: Onder de prent staat: Amsterdam, februari 1941, waarmee Jordaan verwijst naar een staking die in februari 1941 onder arbeiders in Amsterdam uitbreekt. De man achter de arm is Mussert, de leider van de Nederlandse partij NSB (Nationaal Socialistische Beweging).
Bij het rechterdeel van de prent: Onder de prent staat Berlijn, juni 1953. De mannen achter de arm zijn Ulbricht en Grotewohl, leiders van de DDR.$$, 'inline'),
  ('c29880d4-3fb9-4b14-8990-a0fb5a81e363', '1f8f488b-d3f8-4719-b1b6-38c3960fcfd6', $$bron 10: artikel in de Volkskrant over het loonvoorstel van Carl Romme (1953)$$,
   $$geschiedenis-havo-2022-ii-nederland-1948-2008-bron10.png$$,
   $$bron 10 In de Volkskrant van 21 oktober 1953 staat in een artikel over een voorstel van Carl Romme, de fractieleider van de Katholieke Volkspartij (KVP):
Prof. Romme heeft vanmiddag in de Tweede Kamer namens de KVP-fractie voorstellen gedaan, die zeer belangrijke gevolgen kunnen hebben voor de arbeiders en de middenstand. Hij verdedigde een nieuw systeem voor het vaststellen van de lonen. Daardoor zou het in 1954 mogelijk worden om in de sectoren van het bedrijfsleven (…) de lonen niet slechts 5 procent te verhogen, maar met 6, 7 of 8 procent. Het voorstel werd in een − ongekend lange − motie Romme verder uitgewerkt. (…) De katholieke fractieleider heeft bij dit Kamerdebat dus meteen de knuppel in het hoenderhok gegooid.$$, 'inline'),
  ('aa692779-e78b-4615-816b-6e06fbd111d3', '1f8f488b-d3f8-4719-b1b6-38c3960fcfd6', $$bron 11: prent van Peter van Straaten in Het Parool (1969)$$,
   $$geschiedenis-havo-2022-ii-nederland-1948-2008-bron11.png$$,
   $$bron 11 Deze prent van Peter van Straaten verschijnt op 4 december 1969 in het dagblad Het Parool:
[Afbeelding] Prent: een grote Sinterklaasfiguur zweeft boven een drukke winkelstraat met lichtreclames met ''koop'' en een winkelingang waar een menigte naar binnen dringt.
Toelichting: In het midden van de prent staat ‘koop, koop, koop, koop, koop, koop, koop’. Op de gevel rechts staat ‘INGANG, hedenavond verkoop tot 21 uur’.$$, 'inline'),
  ('0885b89c-c488-435f-a9d3-9e3051c452ed', '1f8f488b-d3f8-4719-b1b6-38c3960fcfd6', $$bron 12: nieuwsbrief van Thera van Osch over gangsta rap (2005)$$,
   $$geschiedenis-havo-2022-ii-nederland-1948-2008-bron12.png$$,
   $$bron 12 In 2005 schrijft Thera van Osch in de nieuwsbrief van de stichting Zij/Hij in beeld:
Gangsta rap is een muzikale subcultuur die een criminele, gewelddadige en vrouwonvriendelijke levensstijl van drugdealers, straatbendes en pooiers verheerlijkt. Kinderen en jongeren worden al vanaf heel jonge leeftijd overstelpt met ranzige clips die gangsta rap dag-in-dag-uit verspreiden via de muziekstations van MTV, the Box en TMF. Gangsta rappers dragen het beeld uit dat je met crimineel geweld en drugshandel een leven van glitter en glamour kunt bereiken. Omringd door zwoele vrouwen lopen ze rond in dure merkkleding, behangen met overdadige sieraden. Ze rijden doelloos rond in luxe auto''s of drinken champagne in exotische villa''s met zwembaden. (…) Sinds kort begint de gangsta rap ook door te dringen in videospelletjes. De gangster rapper "50 Cent" is inmiddels al verheven tot hoofdrolspeler in een nieuwe gewelddadige videogame. Hierdoor kunnen kinderen en jongeren zich nog beter inleven in het vunzig gedrag van de macho, die met misdaad en geweld de top bereikt en een luxeleven kan leiden.$$, 'inline'),
  ('8d7a49d1-f07f-4254-b458-fab4467564b2', 'e91e7b05-d497-4bbd-b91d-7dd15e0114a7', $$bron 8: verslag van generaal Lucius Clay aan de Amerikaanse regering (1946)$$,
   $$geschiedenis-havo-2022-ii-computer-en-televisie-bron8.png$$,
   $$bron 8 Generaal Lucius Clay is in 1946 de plaatsvervangend militair gouverneur van de Amerikaanse bezettingszone in Duitsland. Hij schrijft in een verslag aan de Amerikaanse regering:
We zijn ervan overtuigd dat de bevolking in de Russische bezettingszone ongeveer 1500 calorieën per dag te eten krijgt en dat dit zeker zo blijft tot de volgende oogst. In de Amerikaanse bezettingszone hebben we vooral ingezet op de democratische ontwikkeling (…). Hierdoor heeft de Communistische Partij hier maar weinig bereikt. Het is echter niet zo moeilijk een keuze te maken tussen communist worden op 1500 calorieën per dag of een aanhanger van de democratie worden op 1000 calorieën1).
noot 1 De energiebehoefte van een gemiddeld mens is ongeveer 2000 calorieën per dag.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('b9182a7c-8cb2-4d3e-bef7-5fc1c909061c', '9e177111-e2c3-495d-acde-4fcae06ac974', 1,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Wereldoorlogen — overig (1900-1950)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["chronologie", "ontdekkingsreizen", "East India Company", "trans-Atlantische slavenhandel", "Eerste Wereldoorlog", "atoombom", "Gorbatsjov"]'::jsonb,
   $$Chronologisch ordenen van zes scheepsrampen uit verschillende tijdvakken.$$,
   $$geschiedenis-havo-2022-ii-door-de-tijd-heen-vraag1.png$$, $$De volgende gebeurtenissen gaan over gezonken schepen en staan in willekeurige volgorde:
1 De Leusden was een van de laatste schepen die voor de West-Indische Compagnie Afrikaanse slaafgemaakten vervoerde. Het schip verging voor de kust van Suriname.
2 De Prinz Eugen zonk nadat het schip bij het Bikini-atol (in de Grote Oceaan) was gebruikt voor een van de eerste Amerikaanse atoomproefprogramma''s.
3 De Russische onderzeeër K-278 zonk voor de kust van Noorwegen, doordat er brand was uitgebroken. Ondanks de onder Gorbatsjov verbeterde verhoudingen met het Westen, probeerde de Sovjet-Unie het ongeluk geheim te houden.
4 De SS Mont-Blanc botste op een ander schip, waarbij de lading van explosieven, die bestemd was om Duitse loopgraven in Frankrijk op te blazen, ontplofte.
5 Het vlaggenschip van de Spaanse ontdekkingsreiziger Columbus Santa Maria leed schipbreuk voor de kust van Hispaniola. Van het wrakhout werd de eerste Europese nederzetting in het Caribisch gebied gebouwd.
6 Tijdens een van de eerste reizen van de East India Company zonk de Ascension voor de kust van India, nadat het schip op een zandbank was gelopen. 2p 1 Zet deze gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('fa31e5d9-1169-421a-b09d-2690faad667e', '9e177111-e2c3-495d-acde-4fcae06ac974', 9,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}, {"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["chronologie", "Opstand", "Gouden Eeuw", "Verlichting", "modern imperialisme", "aardgas"]'::jsonb,
   $$Chronologisch ordenen van zes ontwerpen van beroemde Nederlandse gebouwen.$$,
   $$geschiedenis-havo-2022-ii-door-de-tijd-heen-vraag9.png$$, $$De volgende ontwerpen van beroemde Nederlandse gebouwen staan in willekeurige volgorde:
1 Architectenbureau Alberts en Van Huut ontwierp een hoofdkantoor in Groningen voor de Gasunie, het bedrijf dat verantwoordelijk was voor transport en opslag van aardgas.
2 De pas opgerichte Algemene Vereniging Radio Omroep (AVRO) kreeg een studio in Hilversum naar een ontwerp van Ben Merkelbach en Charles Karsten. De omroep kon vanuit deze studio het toenemende aantal radiobezitters bedienen.
3 Kort nadat de Spaanse belegering van de stad Leiden was opgeheven, kreeg Claes van Es de opdracht een nieuwe voorgevel voor het Leidse stadhuis te ontwerpen.
4 Leendert Viervant ontwierp kort na het overlijden van Pieter Teyler het eerste museum van Nederland om natuurhistorische voorwerpen tentoon te stellen. Die voorwerpen had Pieter Teyler verzameld vanuit het verlichte denkbeeld dat kennis moest worden gedeeld.
5 Op landgoed Bronbeek in Arnhem werd naar een ontwerp van Willem Nicolaas Rose een militair invalidentehuis gebouwd. Het tehuis was bedoeld voor militairen die invalide raakten tijdens de strijd om het Nederlandse gezag in de kolonie Nederlands-Indië steeds verder uit te breiden.
6 Voor het stadsbestuur van Amsterdam ontwierp Jacob van Campen een nieuw stadhuis, dat de rijkdom en de centrale positie van de stad in de wereldhandel weergaf. 2p 9 Zet deze gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('ba6d324b-b66b-4da5-8e6b-2c62a5959c3b', '04f9acb7-7f17-43d8-a355-96924ed11311', 2,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}]'::jsonb,
   '["renaissance", "klassieke Oudheid", "humanisme", "bouwkunst", "kenmerkend aspect", "argumenteren"]'::jsonb,
   $$Met twee kenmerkende aspecten beargumenteren dat de werkwijze van Palladio bij de renaissance past.$$,
   $$geschiedenis-havo-2022-ii-ontdekkers-en-hervormers-vraag2.png$$, $$Gebruik bron 1. Een bewering: Palladio''s werkwijze past bij de Renaissancetijd. 4p 2 Geef twee verschillende argumenten voor deze bewering, waarbij je je antwoord telkens ondersteunt met een verschillend kenmerkend aspect. Let op: je mag een kenmerkend aspect maar één keer gebruiken.$$, array['02afe4c6-daf4-4451-8f19-86b5f5aa549f']::uuid[]),
  ('0696c1fa-1f94-4a17-b1ff-db31bb68cc4d', '04f9acb7-7f17-43d8-a355-96924ed11311', 3,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}]'::jsonb,
   '["Reformatie", "anglicaanse kerk", "Opstand", "vestigingskolonie", "Europese expansie", "kenmerkend aspect"]'::jsonb,
   $$Drie gegevens uit het leven van Edward Maria Wingfield koppelen aan verschillende kenmerkende aspecten van de zestiende eeuw.$$,
   $$geschiedenis-havo-2022-ii-ontdekkers-en-hervormers-vraag3.png$$, $$Enkele gegevens uit het leven van Edward Maria Wingfield (1550- 1631):
1 De vader van Wingfield liet zijn zoon opvoeden volgens het anglicaanse geloof. Dit geloof was in Engeland ingevoerd, nadat koning Henry VIII had gebroken met de paus.
2 Wingfield was commandant van een compagnie in dienst van de Republiek. Hij werd bij Bergen op Zoom door Spaanse troepen gevangengenomen.
3 Wingfield vertrok naar de noordoostkust van Amerika, om daar een vestigingskolonie te stichten. 3p 3 Noem bij elk van de gegevens uit het leven van Edward Maria Wingfield een verschillend kenmerkend aspect uit de zestiende eeuw dat hierbij past. Let op: je mag een kenmerkend aspect maar één keer gebruiken.$$, array[]::uuid[]),
  ('993ceda1-e0b0-4a3a-8496-4a7a32411333', '2cb9561d-7c02-48bc-9b14-755c69e765fc', 4,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["Engelse koloniën", "Jamestown", "vestigingskolonie", "betrouwbaarheid", "aard van de bron", "bronkritiek"]'::jsonb,
   $$Uitleggen welke verklaring een brief van John Smith geeft voor het afzetten van koloniepresident Wingfield en waarom de bron betrouwbaar is.$$,
   $$geschiedenis-havo-2022-ii-het-britse-rijk-vraag4.png$$, $$Gebruik bron 2. Eind 1607 wordt Edward Maria Wingfield (zie vraag 3) door zijn medekolonisten afgezet als president van de kolonie in Chesapeake Bay. Je onderzoekt deze gebeurtenis en besluit de brief van John Smith te gebruiken als bron. 3p 4 Ondersteun je keuze door:
− uit te leggen welke verklaring voor het afzetten van Wingfield je aan de brief kunt ontlenen en
− aan te geven dat je de informatie betrouwbaar vindt door de aard van de bron.$$, array['5a18e299-6184-4136-8861-a160843a4873']::uuid[]),
  ('cbaaaa1d-3525-4c06-94b7-494f8de74152', '2cb9561d-7c02-48bc-9b14-755c69e765fc', 7,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["East India Company", "Mogolrijk", "Verdrag van Allahabad", "factorijen", "belastinginning", "keerpunt"]'::jsonb,
   $$Uitleggen hoe een wet uit 1717 en het Verdrag van Allahabad de positie van de East India Company in India versterkten.$$,
   $$geschiedenis-havo-2022-ii-het-britse-rijk-vraag7.png$$, $$In 1717 vaardigde de Mogolvorst Farrukhsiyar een wet uit. Met deze wet gaf hij de East India Company onder andere toestemming om meer dan dertig dorpen te kopen, een fort in de buurt van het dorp Kalikata te verstevigen en er soldaten te legeren. Historici beschouwen de wet uit 1717 als een keerpunt in de geschiedenis van India. 3p 7 Ondersteun deze visie door:
− uit te leggen welke verandering in de positie van de East India Company in India door deze wet mogelijk werd en
− een afspraak uit het verdrag van Allahabad te noemen, waarmee de positie van de East India Company verder werd versterkt.$$, array[]::uuid[]),
  ('2f1cda2e-b6b4-47e3-a17d-7cdb5e3f054b', '2cb9561d-7c02-48bc-9b14-755c69e765fc', 10,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["sati", "Brits gezag", "culturele beïnvloeding", "indirect bestuur", "verzet", "bronverwijzing"]'::jsonb,
   $$Met de petitie tegen het verbod op sati uitleggen dat hindoes het Britse gezag accepteerden maar zich verzetten tegen culturele beïnvloeding.$$,
   $$geschiedenis-havo-2022-ii-het-britse-rijk-vraag10.png$$, $$Gebruik bron 4. De opstellers van deze petitie richten zich tot het Britse bestuur in India. 4p 10 Leg uit, telkens met een verschillende verwijzing naar de bron, dat de opstellers van deze petitie:
− het bestuurlijk gezag van de Britten accepteren maar
− zich verzetten tegen Britse culturele beïnvloeding.$$, array['bc70bb85-4c56-49c6-9232-9e93d397df1d']::uuid[]),
  ('ec6d4e71-a804-4d4b-8d65-d1471e0f7c94', '2cb9561d-7c02-48bc-9b14-755c69e765fc', 11,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["Factory Acts", "sociale kwestie", "fabrieksinspectie", "betrouwbaarheid", "kapitalisme", "werktijdverkorting"]'::jsonb,
   $$Het inspectieverslag over fabrieksarbeid uit 1845 toelichten in relatie tot de Factory Acts, betrouwbaarheid en een kapitalistisch standpunt.$$,
   $$geschiedenis-havo-2022-ii-het-britse-rijk-vraag11.png$$, $$Gebruik bron 5. In het Britse parlement wordt in 1845 gediscussieerd of de Factory Acts moeten worden uitgebreid door de werkdagen te verkorten tot tien uur. 4p 11 Licht het verzenden van het verslag van de inspecteur van fabrieken naar de minister toe door:
− zonder bron aan te geven dat het laten maken van officiële verslagen door inspecteurs de uitvoering van eerdere Factory Acts moet ondersteunen en
− te verklaren dat de informatie in deze verslagen als betrouwbaar beschouwd kan worden en
− uit te leggen dat in de brief de mogelijke uitbreiding van de Factory Acts wordt verdedigd met een kapitalistisch standpunt, waarbij je je antwoord ondersteunt met een verwijzing naar de bron.$$, array['f4227d2f-03f5-4e12-acbf-04aa0539300b']::uuid[]),
  ('0179ee33-7e45-4280-929f-2996527cc5fa', '6c27e968-2150-407d-9558-1f2ed28a9af2', 5,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}]'::jsonb,
   '["West-Indische Compagnie", "Piet Hein", "trans-Atlantische slavenhandel", "Opstand", "Republiek", "Spanje"]'::jsonb,
   $$Verklaren waarom de Republiek de aanvallen van Piet Hein op Portugees-Spaanse gebieden in Brazilië en Angola aanmoedigde.$$,
   $$geschiedenis-havo-2022-ii-regenten-en-vorsten-vraag5.png$$, $$Twee gegevens over Piet Hein, viceadmiraal van de Nederlandse West-Indische Compagnie, die Portugees-Spaanse gebieden aanviel:
1 In 1623 veroverde Piet Hein in Brazilië (in Zuid-Amerika) de stad São Salvador da Bahia.
2 Hierna vertrok Piet Hein met een deel van de vloot naar Angola (in Afrika) met het doel de havenstad Luanda te veroveren. Deze aanvallen op Portugees-Spaanse gebieden werden door het bestuur van de Republiek aangemoedigd. 2p 5 Verklaar deze aanmoediging door aan te geven:
− welke handel in Nederlandse handen moest komen en
− dat deze aanvallen op juist Portugees-Spaanse gebieden de stichting van een Nederlandse staat moesten ondersteunen.$$, array[]::uuid[]),
  ('c8149eff-b023-4857-9fff-7ad2cddce19f', '6c27e968-2150-407d-9558-1f2ed28a9af2', 6,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}]'::jsonb,
   '["wetenschappelijke revolutie", "VOC", "regenten", "Gouden Eeuw", "tropische ziekten", "kenmerkend aspect"]'::jsonb,
   $$Met een kenmerkend aspect verklaren waarom de VOC-regenten het medisch onderzoek van Jacobus de Bondt nodig vonden.$$,
   $$geschiedenis-havo-2022-ii-regenten-en-vorsten-vraag6.png$$, $$De Nederlandse arts Jacobus de Bondt (1592-1631) was als geneesheer in dienst van de Verenigde Oost-Indische Compagnie (VOC). Hij schreef zijn observaties van tropische ziekten en hield aantekeningen bij van zijn pogingen om zieken onder VOC-personeel in India te genezen. 2p 6 Verklaar dat de regenten in het bestuur van de VOC het onderzoek van De Bondt noodzakelijk vonden voor hun onderneming, waarbij je je antwoord met een kenmerkend aspect uit de zeventiende eeuw ondersteunt.$$, array[]::uuid[]),
  ('78064d7e-2189-42c1-8668-16da4874e0f6', 'd149e5ac-d8c1-488d-a064-86690e544424', 8,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Pruiken en revoluties — overig (1700-1800)"}]'::jsonb,
   '["democratische revolutie", "patriotten", "ancien régime", "Bataafse Revolutie", "volkssoevereiniteit", "bronverwijzing"]'::jsonb,
   $$Met een verwijzing naar de bron aantonen dat Daendels in 1794 opriep tot een democratische revolutie.$$,
   $$geschiedenis-havo-2022-ii-pruiken-en-revoluties-vraag8.png$$, $$Gebruik bron 3. Daendels roept op tot een democratische revolutie. 2p 8 Toon dit aan, waarbij je je antwoord ondersteunt met een verwijzing naar de bron.$$, array['1a46eacb-4c6a-469e-9996-44457d7d99da']::uuid[]),
  ('7ebac434-c2c3-4136-aaa7-1d9f6069f655', 'd17ee76f-423a-4a8c-88d5-ed101ed4c40e', 18,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["crisis van de jaren '30", "Olympische Spelen 1936", "propaganda", "totalitarisme", "nationaalsocialisme", "kenmerkend aspect"]'::jsonb,
   $$Met twee kenmerkende aspecten uitleggen welke economische en politieke kritiek er was op Nederlandse deelname aan de Olympische Spelen van 1932 en 1936.$$,
   $$geschiedenis-havo-2022-ii-tijd-van-wereldoorlogen-vraag18.png$$, $$In Nederland was kritiek op de deelname van het Nederlandse team aan de Olympische Spelen van 1932 in Los Angeles (in de Verenigde Staten) en aan de Olympische Spelen van 1936 in Berlijn. De kritiek op de Nederlandse deelname werd ondersteund met een economisch argument in 1932 en met een politiek argument in 1936. 4p 18 Leg voor beide jaren uit wat de kritiek op de Nederlandse deelname was, waarbij je je antwoord telkens ondersteunt met een verschillend kenmerkend aspect. Let op: je mag een kenmerkend aspect maar één keer gebruiken.$$, array[]::uuid[]),
  ('4e42e75d-960c-4067-8cbd-92fbbcae22a9', 'd17ee76f-423a-4a8c-88d5-ed101ed4c40e', 24,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["Gorbatsjov", "Brezjnevdoctrine", "Oostblok", "val van de Muur", "einde Koude Oorlog", "buitenlands beleid"]'::jsonb,
   $$Uitleggen welke koerswijziging de 'Frank-Sinatra-doctrine' aanduidde en welk gevolg Dan Quayle voorspelde.$$,
   $$geschiedenis-havo-2022-ii-tijd-van-wereldoorlogen-vraag24.png$$, $$Twee gegevens:
1 Op 25 oktober 1989 zei Gennadi Gerasimov, de woordvoerder van het ministerie van Buitenlandse Zaken van de Sovjet-Unie, tegen westerse journalisten: "Ken je het lied My way (Mijn manier) van Frank Sinatra? Oost- Europa doet het nu op hun manier."
2 De Amerikaanse vicepresident Dan Quayle zei hierop: "Ze praten over de Frank-Sinatra-doctrine, maar ze zouden ook moeten denken aan de Nancy-Sinatra-doctrine (de dochter van Frank) met haar lied These boots are made for walking (Deze laarzen zijn gemaakt om mee te lopen)." 3p 24 Licht de gegevens toe door:
− uit te leggen welke koerswijziging in het buitenlands beleid van de Sovjet-Unie met de ''Frank-Sinatra- doctrine'' werd aangeduid en
− aan te geven welk gevolg van deze koerswijziging door Dan Quayle werd voorspeld met de ''Nancy-Sinatra-doctrine''.$$, array[]::uuid[]),
  ('8b351c82-012b-4043-943a-4b243126158d', '994edf08-89c6-4f2d-8991-03d9319e54f3', 12,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["sociale kwestie", "socialisme", "arbeiderswoningen", "liberalisme", "overheidsingrijpen", "christelijke normen"]'::jsonb,
   $$Aangeven bij welk socialistisch streven het woningproject van Octavia Hill paste en welke kritiek socialisten erop hadden.$$,
   $$geschiedenis-havo-2022-ii-burgers-en-stoommachines-vraag12.png$$, $$Octavia Hill (1838-1912) zette zich in voor hervormingen in Groot-Brittannië. Een van haar projecten was het verhuren van nette huizen aan arme arbeidersgezinnen. Twee gegevens over dit project:
1 Octavia Hill hield toezicht op het naleven van christelijke normen en waarden door haar huurders.
2 Octavia Hill wees grootschalige projecten van de overheid af die de huisvestiging van arbeiders moesten verbeteren. Socialisten reageerden wisselend op het werk van Octavia Hill. 3p 12 Geef aan:
− bij welk socialistisch streven dit project van Octavia Hill paste en
− voor beide gegevens apart, welke kritiek de socialisten hadden op de uitgangspunten van Hill.$$, array[]::uuid[]),
  ('5f1f995c-d153-48d2-8572-52ea79a9d4b5', '994edf08-89c6-4f2d-8991-03d9319e54f3', 13,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["nationalisme", "industriële revolutie", "grondstoffen", "Frans-Duitse oorlog", "Elzas-Lotharingen", "kenmerkend aspect"]'::jsonb,
   $$Met twee kenmerkende aspecten van de negentiende eeuw verklaren waarom Duitsland Elzas-Lotharingen wilde bezitten.$$,
   $$geschiedenis-havo-2022-ii-burgers-en-stoommachines-vraag13.png$$, $$Na de Frans-Duitse oorlog van 1870-1871 moest Frankrijk Elzas-Lotharingen aan Duitsland afstaan. Dit gebied was rijk aan delfstoffen en had een in meerderheid Duitssprekende bevolking. 2p 13 Noem twee kenmerkende aspecten van de negentiende eeuw die verklaren dat Duitsland juist Elzas-Lotharingen in bezit wilde nemen.$$, array[]::uuid[]),
  ('be161952-488d-494a-b970-14782be2d5b6', '994edf08-89c6-4f2d-8991-03d9319e54f3', 14,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["emancipatie", "katholieken", "democratisering", "kiesrecht", "confessionalisme", "verkiezingen"]'::jsonb,
   $$Met de herinnering van Gerard Brom uitleggen dat democratisering de emancipatie van katholieken bevorderde.$$,
   $$geschiedenis-havo-2022-ii-burgers-en-stoommachines-vraag14.png$$, $$Gebruik bron 6. 2p 14 Leg uit dat je met deze herinnering van Gerard Brom kunt aantonen dat de emancipatie van de katholieken in Nederland wordt bevorderd door de voortschrijdende democratisering.$$, array['4672919d-7a12-45c9-a440-7086fdda3cd9']::uuid[]),
  ('d3a35d66-58f6-4752-b53f-9721afe7d3da', 'e1b46de3-9810-4f87-ad4a-f5d6678e2c05', 15,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["Verdrag van Versailles", "verzoeningspolitiek", "Volksgemeinschaft", "Duitse eenheid", "Europese integratie", "Ostpolitik"]'::jsonb,
   $$Vier politieke ontwikkelingen in Duitsland koppelen aan gebeurtenissen rond het monument Deutsches Eck.$$,
   $$geschiedenis-havo-2022-ii-duitsland-in-europa-vraag15.png$$, $$In de Duitse stad Koblenz werd een ruiterstandbeeld van keizer Wilhelm I opgericht vanwege zijn rol bij de eenwording van Duitsland. Hieronder staan vijf gebeurtenissen (a t/m e) in chronologische volgorde die te maken hebben met dit monument, dat Deutsches Eck werd genoemd. a Rijkspresident Von Hindenburg bezocht het Deutsches Eck nadat Franse troepen zich hadden teruggetrokken uit het Rijnland, vier jaar eerder dan was bepaald bij het Verdrag van Versailles. b De plaatselijke leiders van de NSDAP lieten een spandoek aan het monument bevestigen met de tekst: ”Het Rijk zal nooit vernietigd worden als je verenigd en loyaal bent”. c Nadat het ruiterstandbeeld was verwoest onthulde de eerste president van de Bondsrepubliek, Theodor Heuss, de overgebleven sokkel met de wapenschilden van alle deelstaten van het oude Duitsland erop als Duits gedenkteken. d Om de betrekking met de DDR niet te schaden keerden politici in de Bondsrepubliek zich tegen een burgerinitiatief om het ruiterstandbeeld van keizer Wilhelm I te herstellen. e Tijdens het plaatsen van een replica van het oude ruiterstandbeeld van keizer Wilhelm I werd geprotesteerd dat hierdoor Duits nationalisme verheerlijkt werd, waardoor de betrekkingen met West-Europese landen zouden verslechteren. Hieronder staan vier politieke ontwikkelingen in Duitsland (1 t/m 4) in willekeurige volgorde:
1 De Duitse bevolking werd genazificeerd.
2 De Duitse regering maakte afspraken over de verzoeningspolitiek.
3 De Duitse regering streefde naar integratie in Europa, waarin zij een leidende rol op zich nam.
4 De regering van de Bondsrepubliek hield vast aan het streven naar Duitse eenheid. 2p 15 Geef per politieke ontwikkeling de gebeurtenis die daarbij past. Noteer alleen de cijfers en de daarbij behorende letters. Let op: er blijft 1 gebeurtenis over.$$, array[]::uuid[]),
  ('b46f8d95-efd9-4fd0-b0b1-7d92b4428ddd', 'e1b46de3-9810-4f87-ad4a-f5d6678e2c05', 16,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["Verdrag van Versailles", "herstelbetalingen", "Elzas-Lotharingen", "grondstoffen", "Republiek van Weimar", "verband uitleggen"]'::jsonb,
   $$Uitleggen welke afspraak uit het Verdrag van Versailles Duitsland moeilijker kon nakomen door het verlies van Elzas-Lotharingen.$$,
   $$geschiedenis-havo-2022-ii-duitsland-in-europa-vraag16.png$$, $$In 1919 werd Elzas-Lotharingen (zie vraag 13) door een afspraak in de Vrede van Versailles weer officieel Frans grondgebied. 2p 16 Leg uit welke andere afspraak uit de Vrede van Versailles Duitsland hierdoor moeilijker kon nakomen.$$, array[]::uuid[]),
  ('7a0b9ebc-2622-42ee-94ee-b884f1439e4d', 'e1b46de3-9810-4f87-ad4a-f5d6678e2c05', 17,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["nationaalsocialisme", "antisemitisme", "propaganda", "Volksgemeinschaft", "gelijkschakeling", "totalitarisme"]'::jsonb,
   $$Uitleggen welke twee nationaalsocialistische opvattingen naar voren komen in een NSDAP-instructie over kranten uit 1933.$$,
   $$geschiedenis-havo-2022-ii-duitsland-in-europa-vraag17.png$$, $$Gebruik bron 7. In deze instructie komen nationaalsocialistische opvattingen naar voren. 4p 17 Leg dit voor twee verschillende opvattingen uit.$$, array['67d22d47-fc4d-4505-b341-a705a50fdcaf']::uuid[]),
  ('3f435cda-1ae7-4000-b017-6c8e8cb887d7', 'e1b46de3-9810-4f87-ad4a-f5d6678e2c05', 20,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["DDR", "opstand 1953", "Ulbricht", "Oostblok", "spotprent", "Februaristaking"]'::jsonb,
   $$Uitleggen welke mening Jordaan in een spotprent uit 1953 weergeeft over het DDR-bewind en de machtsverhoudingen in het Oostblok.$$,
   $$geschiedenis-havo-2022-ii-duitsland-in-europa-vraag20.png$$, $$Gebruik bron 9. Jordaan geeft een mening weer over de regering van de DDR. 4p 20 Leg uit, telkens met een verschillende verwijzing naar de bron, welke mening Jordaan weergeeft:
− over het regeringsbeleid in de DDR door de verwijzing naar de situatie in Nederland in 1941 en
− over de machtsverhoudingen in het Oostblok in 1953.$$, array['297098e5-aebe-4f65-afde-07ea95d51735']::uuid[]),
  ('28e20e5c-9f34-4a95-a19a-321cd705ad80', '1f8f488b-d3f8-4719-b1b6-38c3960fcfd6', 21,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["geleide loonpolitiek", "wederopbouw", "KVP", "verzuiling", "kabinet-Drees", "coalitie"]'::jsonb,
   $$Aangeven welk loonbeleid Romme in 1953 wilde veranderen en verklaren welk politiek probleem dat in de regering gaf.$$,
   $$geschiedenis-havo-2022-ii-nederland-1948-2008-vraag21.png$$, $$Gebruik bron 10. De verandering die Romme wil doorvoeren in het beleid van de regering zorgt voor een politiek probleem. 2p 21 Licht dit toe door:
− met bron aan te geven welk beleid Romme wil veranderen en
− zonder bron te verklaren voor welk politiek probleem dit zorgt in de regering.$$, array['c29880d4-3fb9-4b14-8990-a0fb5a81e363']::uuid[]),
  ('a3282836-4993-4503-941a-d60332fd9d02', '1f8f488b-d3f8-4719-b1b6-38c3960fcfd6', 22,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["consumptiemaatschappij", "welvaartsgroei", "spotprent", "commercialisering", "jaren 1960", "bronverwijzing"]'::jsonb,
   $$Uitleggen welke mening Peter van Straaten in 1969 gaf over de opkomst van de consumptiemaatschappij.$$,
   $$geschiedenis-havo-2022-ii-nederland-1948-2008-vraag22.png$$, $$Gebruik bron 11. In deze prent geeft Van Straaten een mening weer over een economische ontwikkeling in Nederland vanaf de jaren 1960. 2p 22 Leg uit welke mening Van Straaten weergeeft, waarbij je je antwoord ondersteunt met een verwijzing naar de bron.$$, array['aa692779-e78b-4615-816b-6e06fbd111d3']::uuid[]),
  ('f751dcd2-a05b-4ae1-907d-7e22cb68c562', '1f8f488b-d3f8-4719-b1b6-38c3960fcfd6', 23,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}]'::jsonb,
   '["Verdrag van Schengen", "gedoogbeleid", "softdrugs", "vrij personenverkeer", "Europese integratie", "open grenzen"]'::jsonb,
   $$Uitleggen waarom het Verdrag van Schengen overleg tussen Nederland en West-Duitsland over het softdrugsbeleid noodzakelijk maakte.$$,
   $$geschiedenis-havo-2022-ii-nederland-1948-2008-vraag23.png$$, $$Na de ondertekening van het Verdrag van Schengen moest over de invoering hiervan worden onderhandeld. Nederland en West-Duitsland overlegden uitgebreid over het softdrugsbeleid in beide landen. 3p 23 Licht dit toe door:
− de kern van het softdrugsbeleid in Nederland te noemen en
− uit te leggen dat juist de ondertekening van het Verdrag van Schengen gesprekken tussen Nederland en West-Duitsland hierover noodzakelijk maakte.$$, array[]::uuid[]),
  ('22df3735-6120-435f-ae03-cfb500ef1623', '1f8f488b-d3f8-4719-b1b6-38c3960fcfd6', 25,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}]'::jsonb,
   '["NAVO", "einde Koude Oorlog", "troonrede", "buitenlands beleid", "Europese integratie", "1990"]'::jsonb,
   $$Uitleggen welke boodschap de regering in de troonrede van 1990 gaf over de politieke rol van Nederland in Europa.$$,
   $$geschiedenis-havo-2022-ii-nederland-1948-2008-vraag25.png$$, $$Op Prinsjesdag 1990 stond in de jaarlijkse troonrede: "In de NAVO treedt de militaire functie minder op de voorgrond; haar politieke taak wint in het veranderde Europa daarentegen aan belang." 2p 25 Leg uit welke boodschap de regering wilde overbrengen over de politieke rol van Nederland in Europa door het opnemen van deze uitspraak.$$, array[]::uuid[]),
